   "options": [
    { "letter": "A", "text": "\"codecommit:CreateBranch\"\n\"codecommit:DeleteBranch\"" },
    { "letter": "B", "text": "\"codecommit:Put*\"" },
    { "letter": "C", "text": "\"codecommit:Update*\"" },
    { "letter": "D", "text": "\"codecommit:*\"" }
   ],
